import { Group, Mesh, PlaneGeometry, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, vec3, vec4, float, mix, texture, fract, sin, dot } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const root = new THREE.Group();
  root.name = 'journal-title';

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d', paper: '#e8ecf2', accent: '#ff2a38', surface: '#0b0b10'
  };

  // spec colors as linear-ish fractions
  const cInk = vec3(float(0x16).div(255), float(0x16).div(255), float(0x1d).div(255));
  const cSurface = vec3(float(0x0b).div(255), float(0x0b).div(255), float(0x10).div(255));

  // atlas region
  const rect = config.atlasRegion?.sourceRect ?? { x: 0, y: 0, w: 512, h: 320 };
  const aw = rect.w ?? 512;
  const ah = rect.h ?? 320;
  const aspect = aw / ah; // 1.6
  const planeW = 2.0;
  const planeH = planeW / aspect; // 1.25

  // ---------- inner wrapper (for entrance anim; root gets scene transform by adapter) ----------
  const inner = new THREE.Group();
  root.add(inner);

  // ---------- backdrop gradient plate (avoid void, engineered gradient) ----------
  const backGeo = new THREE.PlaneGeometry(planeW + 0.35, planeH + 0.25);
  const backMat = new MeshBasicNodeMaterial();
  backMat.transparent = true;
  backMat.depthWrite = false;
  const gradRGB = mix(cSurface, cInk, uv().y);
  backMat.colorNode = vec4(gradRGB, float(0.9));
  const back = new Mesh(backGeo, backMat);
  back.position.z = -0.06;
  back.renderOrder = -1;
  inner.add(back);

  // ---------- sprite plane (floating-accent.png) ----------
  const spriteGeo = new THREE.PlaneGeometry(planeW, planeH);
  const spriteMat = new MeshBasicNodeMaterial();
  spriteMat.transparent = true;
  spriteMat.depthWrite = false;

  const sprite = new Mesh(spriteGeo, spriteMat);
  sprite.renderOrder = 1;
  inner.add(sprite);

  // subtle static grain (uv-based hash, no time)
  const grainUV = uv().mul(float(800.0));
  const h = fract(sin(dot(grainUV, vec2(float(127.1), float(311.7)))).mul(float(43758.5453)));
  const grainAmt = float(0.04);

  // ---------- text overlay: "Journal" ----------
  const textGroup = new THREE.Group();
  textGroup.position.z = 0.02;
  inner.add(textGroup);
  const textObjs = [];
  for (const item of items) {
    if (!item || !item.text) continue;
    const role = item?.role ?? 'headline';
    const fs = (item.typography?.fontSize ?? 96);
    const t = ctx.fontAtlas.createText(String(item.text), {
      fontSize: fs,
      color: colors.paper ?? '#e8ecf2',
      align: role === 'headline' ? 'center' : 'left',
    });
    // MSDF text arrives sized in px; scale to scene units (headline ~0.34 em height)
    const scale = 0.0042;
    t.scale.setScalar(scale);
    t.position.set(0, 0, 0);
    textGroup.add(t);
    textObjs.push(t);
  }

  // ---------- billboarding: face the camera each frame ----------
  sprite.onBeforeRender = (_renderer, _scene, camera) => {
    sprite.quaternion.copy(camera.quaternion);
    back.quaternion.copy(camera.quaternion);
    textGroup.quaternion.copy(camera.quaternion);
  };

  // ---------- texture load + grain composition ----------
  let disposed = false;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      if (disposed) { tex.dispose?.(); return; }
      tex.colorSpace = THREE.SRGBColorSpace;
      tex.minFilter = THREE.LinearFilter;
      tex.magFilter = THREE.LinearFilter;
      tex.generateMipmaps = false;
      // atlas UV offset/repeat (assume texture natural size == atlas page)
      try {
        const img = tex.image;
        const iw = (img && (img.width || img.naturalWidth)) || aw;
        const ih = (img && (img.height || img.naturalHeight)) || ah;
        tex.offset.set(rect.x / iw, 1.0 - (rect.y + ah) / ih);
        tex.repeat.set(aw / iw, ah / ih);
      } catch (e) { /* leave default */ }

      const texNode = texture(tex, uv());
      const base = texNode.rgb;
      const outRGB = base.mul(float(1).sub(grainAmt).add(h.mul(grainAmt)));
      spriteMat.colorNode = vec4(outRGB, texNode.a);
      spriteMat.needsUpdate = true;
      sprite.userData.__tex = tex;
    }).catch(() => {});
  } else {
    // fallback: faint accent plate so node never reads as void
    const cAccent = vec3(float(0xff).div(255), float(0x2a).div(255), float(0x38).div(255));
    const fbRGB = mix(cSurface, cAccent, uv().y.mul(0.5));
    spriteMat.colorNode = vec4(fbRGB, float(0.18));
  }

  // ---------- entrance: rise-in + fade (one-shot, no idle) ----------
  const tl = gsap.timeline();
  inner.position.y = 0.4;
  const mats = [backMat, spriteMat];
  mats.forEach((m) => { m.opacity = 0; });
  tl.to(inner.position, { y: 0, duration: 0.7, ease: 'power3.out' }, 0);
  tl.to(backMat, { opacity: 0.9, duration: 0.6, ease: 'power2.out' }, 0);
  tl.to(spriteMat, { opacity: 1.0, duration: 0.6, ease: 'power2.out' }, 0);
  textObjs.forEach((t) => {
    if (t.material) {
      t.material.transparent = true;
      t.material.opacity = 0;
      tl.to(t.material, { opacity: 1, duration: 0.6, ease: 'power2.out' }, 0.08);
    }
  });

  // ---------- handlers (spec: none) ----------
  root.userData.handlers = {};

  // ---------- cleanup ----------
  root.userData.cleanup = () => {
    disposed = true;
    tl.kill();
    sprite.onBeforeRender = null;
    spriteGeo.dispose();
    backGeo.dispose();
    spriteMat.dispose();
    backMat.dispose();
    if (sprite.userData.__tex) sprite.userData.__tex.dispose?.();
    textObjs.forEach((t) => {
      t.geometry?.dispose?.();
      if (Array.isArray(t.material)) t.material.forEach((m) => m.dispose?.());
      else t.material?.dispose?.();
    });
  };

  return root;
}
